"use strict";
// Draft Helper (Minify mod)
// Shows the best heroes for your position during hero selection, based on the
// enemies and teammates already picked. Data comes from minify_draft_helper_data.js,
// generated by the mod's script.py when patching (MDH_DATA / MDH_CONFIG globals).

var MinifyDraftHelper = (function () {
  const TEAM_RADIANT = 2;
  const TEAM_DIRE = 3;
  const ROWS = 8;
  const MIN_SIZE = 1;
  const MAX_SIZE = 5;
  const SIZE_TO_SCALE = { 1: 70, 2: 85, 3: 100, 4: 120, 5: 140 };
  const MIN_SCALE = 50;
  const MAX_SCALE = 200;
  const NORMAL_WIDTH = 520;
  const WIDE_WIDTH = 780;
  const WIDE_THRESHOLD = 700;
  const SPLIT_WIDTH = 900;
  const SPLIT_WIDE_THRESHOLD = 1150;
  const MIN_WIDTH = 420;
  const MAX_WIDTH = 1400;
  const STATE_ATTRIBUTE_BASE = "minify_draft_helper_state";
  const TICK_SECONDS = 0.5;
  const COMMAND_NAME = "minify_draft_helper_toggle";

  const DATA = typeof MDH_DATA !== "undefined" ? MDH_DATA : null;
  const CFG = typeof MDH_CONFIG !== "undefined" && MDH_CONFIG ? MDH_CONFIG : {};
  const ST = DATA && DATA.stratz ? DATA.stratz : null;
  // The same script runs in the draft screen and in the main menu / lobby (dashboard)
  const IN_MENU = (() => {
    try {
      return $.GetContextPanel().paneltype === "DOTADashboard";
    } catch (e) {
      return false;
    }
  })();
  const DP_SCALE = DATA && DATA.dpScale ? DATA.dpScale : null;
  const ITEM_SLOTS = 6;

  // Strategy-map lane hit boxes, copied from dota_hud_hero_picking_minimap.css (percentages).
  // Lane names are map-absolute; they are turned into safe/off lanes per team later.
  const LANE_BOXES = [
    ["BottomRadiant", "bot", 29, 78, 65, 22],
    ["TopRadiant", "top", 3, 19, 10, 47],
    ["TopRadiant2", "top", 12, 37, 20, 27],
    ["JungleRadiant", "jungle", 36, 63, 49, 15],
    ["MidRadiant", "mid", 25, 52, 21, 21],
    ["TopDire", "top", 6, 0, 63, 22],
    ["BottomDire", "bot", 85, 35, 10, 47],
    ["BottomDire2", "bot", 68, 39, 17, 23],
    ["JungleDire", "jungle", 16, 23, 53, 13],
    ["JungleDire2", "jungle", 33, 36, 14, 7],
    ["MidDire", "mid", 47, 31, 21, 21],
  ];

  const STRINGS = {
    english: {
      title: "Draft Helper",
      pos: "Pos",
      auto: "Auto",
      hero: "Hero",
      total: "Total",
      vs: "vs",
      with: "with",
      wrvs: "WR vs",
      wr: "WR",
      early: "Early",
      mid: "Mid",
      late: "Late",
      noData: "No hero data. Patch with internet access to download it.",
      spectator: "Not available for spectators.",
      meta: "outside a match: best heroes by winrate",
      metaPick: "pick a position",
      enemies: "enemies",
      allies: "allies",
      yourPos: "your pos",
      any: "any",
      lanes: { safe: "safe", off: "off", mid: "mid", jungle: "jungle" },
      manual: "manual",
      autoUnknown: "auto: place your icon on the map",
      situational: "situational pick",
      vsLine: "vs",
      withLine: "with",
      tooltipTotal: "Total = vs enemies + with allies, both sources combined (in standard deviations)",
      wrPos: "WR pos",
      groupDp: "dotapicker",
      groupSt: "STRATZ",
      stMissing: "STRATZ: no data",
      items: "Items",
      itemsTitle: "Best items by winrate",
      itemsNone: "no STRATZ item data",
      matches: "matches",
      clickHint: "click a hero to see items",
      noToken: "no token",
      tooltipTotalOne: "Total = vs enemies + with allies, this source only",
    },
    russian: {
      title: "Draft Helper",
      pos: "Поз",
      auto: "Авто",
      hero: "Герой",
      total: "Итог",
      vs: "Пр.",
      with: "С союз.",
      wrvs: "WR пр.",
      wr: "WR",
      early: "Ран.",
      mid: "Сред.",
      late: "Позд.",
      noData: "Нет данных о героях. Пропатчьте Minify с интернетом, чтобы скачать их.",
      spectator: "Недоступно зрителям.",
      meta: "вне матча: лучшие герои по винрейту",
      metaPick: "выберите позицию",
      enemies: "врагов",
      allies: "союзников",
      yourPos: "ваша поз.",
      any: "любая",
      lanes: { safe: "лёгкая", off: "сложная", mid: "мид", jungle: "лес" },
      manual: "вручную",
      autoUnknown: "авто: поставьте иконку на карте",
      situational: "ситуативный пик",
      vsLine: "против",
      withLine: "вместе с",
      tooltipTotal: "Итог = против врагов + с союзниками, оба источника вместе (в стандартных отклонениях)",
      wrPos: "WR поз.",
      groupDp: "dotapicker",
      groupSt: "STRATZ",
      stMissing: "STRATZ: нет данных",
      items: "Предметы",
      itemsTitle: "Лучшие предметы по винрейту",
      itemsNone: "нет данных STRATZ о предметах",
      matches: "матчей",
      clickHint: "нажмите на героя, чтобы увидеть предметы",
      noToken: "нет токена",
      tooltipTotalOne: "Итог = против врагов + с союзниками, только этот источник",
    },
  };

  let T = STRINGS.english;
  try {
    const lang = $.Language();
    if (lang && STRINGS[lang]) T = STRINGS[lang];
    else if (lang === "ukrainian") T = STRINGS.russian;
  } catch (e) {}

  const state = {
    scale: SIZE_TO_SCALE[clamp(parseInt(CFG.size, 10) || 3, MIN_SIZE, MAX_SIZE)],
    width: NORMAL_WIDTH,
    free: false, // true once the window has been dragged somewhere
    left: 0,
    top: 0,
    collapsed: false,
    hidden: false, // the main menu panel starts hidden, see init()
    manualPos: 0,
    detailHero: 0,
    lastBridge: "",
    lastBridgeTime: 0,
    itemSlots: [],
    split: !!CFG.split,
    tables: {},
    lastSignature: "",
    lastDebug: "",
    rows: [],
  };

  const heroIndexById = {};
  const heroIdByNpc = {};
  if (DATA && DATA.heroes) {
    for (let i = 0; i < DATA.heroes.length; i++) {
      const h = DATA.heroes[i];
      heroIndexById[h.id] = i;
      heroIdByNpc[h.npc] = h.id;
      heroIdByNpc[h.npc.replace("npc_dota_hero_", "")] = h.id;
    }
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function fmt(v) {
    const r = Math.round(v * 10) / 10;
    return (r > 0 ? "+" : "") + r.toFixed(1);
  }

  function ctx() {
    return $.GetContextPanel();
  }

  function el(id) {
    return ctx().FindChildTraverse(id);
  }

  function heroDisplayName(h) {
    try {
      const loc = $.Localize("#" + h.npc);
      if (loc && loc.indexOf("npc_dota_hero") === -1 && loc.charAt(0) !== "#") return loc;
    } catch (e) {}
    return h.name;
  }

  // ------------------------------------------------------------------ roles

  function has(list, role) {
    return !!list && list.indexOf(role) !== -1;
  }

  // 2 = natural role, 1 = situational, 0 = not played there.
  // With STRATZ data this uses how often the hero is really played on that position.
  function positionFit(h, pos, heroIdx, source) {
    if (!pos) return 2;
    if (ST && source !== "dp" && ST.share[heroIdx]) {
      const shares = ST.share[heroIdx];
      if (shares[0] + shares[1] + shares[2] + shares[3] + shares[4] > 0) {
        const share = shares[pos - 1];
        return share >= 12 ? 2 : share >= 4 ? 1 : 0;
      }
    }
    const r = h.roles || [];
    const c = h.canRoles || [];
    const support = has(r, "RoleSupport") || has(r, "LaneSupport");
    switch (pos) {
      case 1:
        if (has(r, "SafelaneCarry")) return 2;
        return has(c, "SafelaneCarry") || has(r, "RoleCarry") ? 1 : 0;
      case 2:
        if (has(r, "Mid")) return 2;
        return has(c, "Mid") ? 1 : 0;
      case 3:
        if (has(r, "Offlane")) return 2;
        return has(c, "Offlane") ? 1 : 0;
      case 4:
        if (has(r, "Roamer") || support) return 2;
        return has(c, "Roamer") || has(c, "LaneSupport") || has(c, "RoleSupport") ? 1 : 0;
      case 5:
        if (has(r, "LaneSupport") || has(r, "RoleSupport")) return 2;
        return has(c, "LaneSupport") || has(c, "RoleSupport") ? 1 : 0;
      default:
        return 2;
    }
  }

  // > 0 means the hero is usually played as a core
  function coreness(h) {
    if (!h) return 0;
    const idx = heroIndexById[h.id];
    if (ST && idx !== undefined && ST.share[idx]) {
      const sh = ST.share[idx];
      if (sh[0] + sh[1] + sh[2] + sh[3] + sh[4] > 0) return (sh[0] + sh[1] + sh[2] - sh[3] - sh[4]) / 20;
    }
    const r = h.roles || [];
    let s = 0;
    if (has(r, "Core")) s += 2;
    if (has(r, "RoleCarry")) s += 2;
    if (has(r, "SafelaneCarry") || has(r, "Mid") || has(r, "Offlane")) s += 1;
    if (has(r, "RoleSupport")) s -= 2;
    if (has(r, "LaneSupport")) s -= 2;
    if (has(r, "Roamer")) s -= 1;
    return s;
  }

  // ------------------------------------------------------------------ players

  function heroIdForPlayer(pid) {
    try {
      const id = Players.GetSelectedHeroID(pid);
      if (id > 0 && heroIndexById[id] !== undefined) return id;
    } catch (e) {}
    try {
      const name = Players.GetPlayerSelectedHero(pid);
      if (name && heroIdByNpc[name] !== undefined) return heroIdByNpc[name];
    } catch (e) {}
    return 0;
  }

  // The hero the local player is hovering (not locked in yet), if the API exposes it
  function tentativeHeroForLocal() {
    try {
      const info = Game.GetLocalPlayerInfo();
      const name = info && info.possible_hero_selection;
      if (name && heroIdByNpc[name] !== undefined) return heroIdByNpc[name];
    } catch (e) {}
    return 0;
  }

  // Outside a match (main menu, lobby) there are no picks: an empty "meta" draft ranks heroes by winrate
  function metaDraft() {
    return { local: -1, team: 0, allies: [], enemies: [], tentative: 0, meta: true };
  }

  function readDraft() {
    if (IN_MENU) return metaDraft();
    const local = Game.GetLocalPlayerID();
    if (local === undefined || local < 0) return metaDraft();
    const team = Players.GetTeam(local);
    if (team !== TEAM_RADIANT && team !== TEAM_DIRE) return null;
    const enemyTeam = team === TEAM_RADIANT ? TEAM_DIRE : TEAM_RADIANT;

    const allies = [];
    const enemies = [];
    const allyIds = Game.GetPlayerIDsOnTeam(team) || [];
    const enemyIds = Game.GetPlayerIDsOnTeam(enemyTeam) || [];
    for (let i = 0; i < allyIds.length; i++) {
      const pid = allyIds[i];
      allies.push({ pid: pid, hero: heroIdForPlayer(pid), local: pid === local });
    }
    for (let i = 0; i < enemyIds.length; i++) {
      const pid = enemyIds[i];
      enemies.push({ pid: pid, hero: heroIdForPlayer(pid) });
    }
    return { local: local, team: team, allies: allies, enemies: enemies, tentative: tentativeHeroForLocal() };
  }

  // ------------------------------------------------------------------ lanes from the strategy map

  function heroIdFromIcon(icon) {
    const ids = ["ForegroundHeroImage", "BackgroundHeroImage"];
    for (let i = 0; i < ids.length; i++) {
      const img = icon.FindChildTraverse(ids[i]);
      if (!img) continue;
      try {
        const id = parseInt(img.heroid, 10);
        if (id > 0 && heroIndexById[id] !== undefined) return id;
      } catch (e) {}
      try {
        const name = img.heroname;
        if (name && heroIdByNpc[name] !== undefined) return heroIdByNpc[name];
      } catch (e) {}
    }
    return 0;
  }

  function laneAt(x, y) {
    let best = null;
    let bestArea = 1e9;
    for (let i = 0; i < LANE_BOXES.length; i++) {
      const b = LANE_BOXES[i];
      if (x >= b[2] && x <= b[2] + b[4] && y >= b[3] && y <= b[3] + b[5]) {
        const area = b[4] * b[5];
        if (area < bestArea) {
          best = b[1];
          bestArea = area;
        }
      }
    }
    if (best) return best;
    // Not inside any box: take the closest box centre if it is reasonably near
    let bestDist = 1e9;
    for (let i = 0; i < LANE_BOXES.length; i++) {
      const b = LANE_BOXES[i];
      const dx = b[2] + b[4] / 2 - x;
      const dy = b[3] + b[5] / 2 - y;
      const d = dx * dx + dy * dy;
      if (d < bestDist) {
        bestDist = d;
        best = b[1];
      }
    }
    return bestDist < 18 * 18 ? best : null;
  }

  // Returns [{hero, lane, x, y, tentative, classes}] for the icons placed on a strategy minimap
  function readMinimapIcons() {
    const maps = ["HeroPickMinimap", "StrategyMinimap"];
    for (let m = 0; m < maps.length; m++) {
      const minimap = el(maps[m]);
      if (!minimap) continue;
      const holder = minimap.FindChildTraverse("HeroImages");
      if (!holder) continue;
      const w = holder.actuallayoutwidth || minimap.actuallayoutwidth;
      const h = holder.actuallayoutheight || minimap.actuallayoutheight;
      if (!(w > 0 && h > 0)) continue;

      const icons = [];
      const count = holder.GetChildCount();
      for (let i = 0; i < count; i++) {
        const icon = holder.GetChild(i);
        if (!icon || icon.BHasClass("Destroying")) continue;
        const x = ((icon.actualxoffset + icon.actuallayoutwidth / 2) / w) * 100;
        const y = ((icon.actualyoffset + icon.actuallayoutheight / 2) / h) * 100;
        icons.push({
          hero: heroIdFromIcon(icon),
          lane: laneAt(x, y),
          x: Math.round(x),
          y: Math.round(y),
          tentative: icon.BHasClass("HeroPickTentative"),
          classes: icon.actualclassnames || "",
          source: maps[m],
        });
      }
      if (icons.length > 0) return icons;
    }
    return [];
  }

  function teamLane(lane, team) {
    if (lane === "mid" || lane === "jungle") return lane;
    if (lane === "bot") return team === TEAM_RADIANT ? "safe" : "off";
    if (lane === "top") return team === TEAM_RADIANT ? "off" : "safe";
    return null;
  }

  // Assigns a lane and a position (1-5) to every ally that placed an icon on the map
  function detectPositions(draft, icons) {
    const used = {};
    const byPid = {};
    const heroOf = (a) => a.hero || (a.local ? draft.tentative : 0);

    for (let i = 0; i < draft.allies.length; i++) {
      const a = draft.allies[i];
      const hid = heroOf(a);
      if (!hid) continue;
      for (let j = 0; j < icons.length; j++) {
        if (!used[j] && icons[j].hero === hid && icons[j].lane) {
          used[j] = true;
          byPid[a.pid] = { lane: teamLane(icons[j].lane, draft.team) };
          break;
        }
      }
    }

    // Local player without a hero yet: if exactly one placed icon is unaccounted for, it's ours
    const me = draft.allies.filter((a) => a.local)[0];
    if (me && !byPid[me.pid]) {
      const pickedEverywhere = {};
      draft.allies.concat(draft.enemies).forEach((p) => {
        if (p.hero) pickedEverywhere[p.hero] = true;
      });
      const free = [];
      for (let j = 0; j < icons.length; j++) {
        if (!used[j] && icons[j].lane && !pickedEverywhere[icons[j].hero]) free.push(j);
      }
      if (free.length === 1) byPid[me.pid] = { lane: teamLane(icons[free[0]].lane, draft.team), guessed: true };
    }

    // Lane -> position. Mid = 2, jungle = 4, safe = 1/5, off = 3/4 (core vs support by hero roles)
    const groups = { safe: [], off: [] };
    Object.keys(byPid).forEach((pid) => {
      const info = byPid[pid];
      if (info.lane === "mid" || info.lane === "jungle") {
        info.pos = info.lane === "mid" ? 2 : 4;
        info.sure = !info.guessed;
      } else if (groups[info.lane]) groups[info.lane].push(parseInt(pid, 10));
    });

    const heroByPid = {};
    draft.allies.forEach((a) => (heroByPid[a.pid] = heroOf(a)));
    const heroData = (pid) =>
      heroByPid[pid] && heroIndexById[heroByPid[pid]] !== undefined ? DATA.heroes[heroIndexById[heroByPid[pid]]] : null;

    ["safe", "off"].forEach((lane) => {
      const corePos = lane === "safe" ? 1 : 3;
      const supPos = lane === "safe" ? 5 : 4;
      const pids = groups[lane];
      if (pids.length === 0) return;
      if (pids.length === 1) {
        const h = heroData(pids[0]);
        byPid[pids[0]].pos = h && coreness(h) < 0 ? supPos : corePos;
        byPid[pids[0]].sure = !!h;
        return;
      }
      // Several heroes in one lane: the most core-like one is the core, the rest support.
      // Unknown heroes (not picked yet) take whatever role is left.
      const scored = pids.map((pid) => {
        const h = heroData(pid);
        return { pid: pid, score: h ? coreness(h) : null };
      });
      const known = scored.filter((s) => s.score !== null).sort((a, b) => b.score - a.score);
      let coreTaken = false;
      if (known.length > 0 && known[0].score > 0) {
        byPid[known[0].pid].pos = corePos;
        byPid[known[0].pid].sure = true;
        coreTaken = true;
      }
      scored.forEach((s) => {
        if (byPid[s.pid].pos) return;
        if (s.score !== null) {
          byPid[s.pid].pos = supPos;
          byPid[s.pid].sure = true;
        } else if (!coreTaken) {
          byPid[s.pid].pos = corePos;
          coreTaken = true;
        } else {
          byPid[s.pid].pos = supPos;
        }
      });
    });

    return byPid;
  }

  // ------------------------------------------------------------------ scoring

  // source: "all" (both sources combined), "dp" (dotapicker only) or "st" (STRATZ only)
  function recommend(draft, pos, source) {
    const n = DATA.n;
    const taken = {};
    const allyIdx = [];
    const enemyIdx = [];
    draft.allies.forEach((a) => {
      if (!a.hero) return;
      taken[a.hero] = true;
      if (!a.local) allyIdx.push(heroIndexById[a.hero]);
    });
    draft.enemies.forEach((e) => {
      if (!e.hero) return;
      taken[e.hero] = true;
      enemyIdx.push(heroIndexById[e.hero]);
    });

    const results = [];
    for (let c = 0; c < n; c++) {
      const h = DATA.heroes[c];
      if (!h.id || taken[h.id]) continue;
      const fit = positionFit(h, pos, c, source);
      if (fit === 0) continue;

      let adv = 0;
      let wvs = 0;
      let stVs = 0;
      const vsList = [];
      for (let k = 0; k < enemyIdx.length; k++) {
        const e = enemyIdx[k];
        const v = DATA.adv[c * n + e] / 10;
        const sv = ST ? ST.vs[c * n + e] / 10 : 0;
        adv += v;
        stVs += sv;
        wvs += DATA.wvs[c * n + e] / 10;
        vsList.push([e, v, sv]);
      }
      let syn = 0;
      let stWith = 0;
      const withList = [];
      for (let k = 0; k < allyIdx.length; k++) {
        const a = allyIdx[k];
        const v = DATA.syn[c * n + a] / 10;
        const sv = ST ? ST.with[c * n + a] / 10 : 0;
        syn += v;
        stWith += sv;
        withList.push([a, v, sv]);
      }

      let total;
      let wrNow = h.wr;
      let penalty = ST ? 1 : 2;
      if (source === "dp") {
        total = adv + syn;
        penalty = 2;
      } else if (source === "st") {
        total = stVs + stWith;
        wrNow = stratzWinrate(c, pos) || 50;
        penalty = 1;
      } else if (ST && DP_SCALE) {
        // Both sources use different units, so each is divided by its typical spread first
        const dpPart = adv / DP_SCALE.adv + syn / DP_SCALE.syn;
        const stPart = stVs / ST.scale.vs + stWith / ST.scale.with;
        total = (dpPart + stPart) / 2;
        wrNow = stratzWinrate(c, pos) || h.wr;
      } else {
        total = adv + syn;
      }
      results.push({
        idx: c,
        hero: h,
        fit: fit,
        adv: adv,
        syn: syn,
        wvs: wvs,
        stVs: stVs,
        stWith: stWith,
        stWr: ST ? stratzWinrate(c, pos) : 0,
        total: total,
        // Situational picks are kept but pushed down a bit
        rank: total - (fit === 1 ? penalty : 0) + (wrNow - 50) * 0.1,
        vsList: vsList,
        withList: withList,
      });
    }
    results.sort((a, b) => b.rank - a.rank);
    return results.slice(0, ROWS);
  }

  // Winrate on the given position (or overall, weighted by how often each position is played)
  function stratzWinrate(c, pos) {
    if (!ST || !ST.posWr[c]) return 0;
    if (pos) return ST.posWr[c][pos - 1] / 10;
    let games = 0;
    let wr = 0;
    for (let p = 0; p < 5; p++) {
      games += ST.share[c][p];
      wr += ST.share[c][p] * ST.posWr[c][p];
    }
    return games ? wr / games / 10 : 0;
  }

  function mainPosition(c) {
    if (!ST || !ST.share[c]) return 0;
    let best = 0;
    for (let p = 1; p < 5; p++) if (ST.share[c][p] > ST.share[c][best]) best = p;
    return ST.share[c][best] > 0 ? best + 1 : 0;
  }

  // ------------------------------------------------------------------ UI

  function createPanel(type, parent, id, props) {
    try {
      if (props) return $.CreatePanel(type, parent, id, props);
    } catch (e) {}
    const p = $.CreatePanel(type, parent, id);
    if (props) {
      Object.keys(props).forEach((k) => {
        try {
          p[k] = props[k];
        } catch (e) {}
      });
    }
    return p;
  }

  function label(parent, cls, text) {
    const l = createPanel("Label", parent, "");
    // AddClass takes a single class name, so "A B" has to be split
    cls.split(" ").forEach((c) => {
      if (c) l.AddClass(c);
    });
    l.text = text;
    return l;
  }

  function showTooltip(panel, text) {
    try {
      $.DispatchEvent("DOTAShowTextTooltip", panel, text);
    } catch (e) {}
  }

  function hideTooltip() {
    try {
      $.DispatchEvent("DOTAHideTextTooltip");
    } catch (e) {}
  }

  // Column sets: "all" = both sources in one list, "dp" / "st" = one source per list (split view)
  const COLUMNS = {
    all: [
      { key: "total", src: "" },
      { key: "adv", src: "dp" },
      { key: "syn", src: "dp" },
      { key: "stVs", src: "st" },
      { key: "stWith", src: "st" },
      { key: "stWr", src: "st" },
      { key: "wvs", src: "dp", wide: true },
      { key: "wr", src: "dp", wide: true },
      { key: "early", src: "dp", wide: true },
      { key: "mid", src: "dp", wide: true },
      { key: "late", src: "dp", wide: true },
    ],
    dp: [
      { key: "total", src: "dp" },
      { key: "adv", src: "dp" },
      { key: "syn", src: "dp" },
      { key: "wr", src: "dp" },
      { key: "wvs", src: "dp", wide: true },
      { key: "early", src: "dp", wide: true },
      { key: "mid", src: "dp", wide: true },
      { key: "late", src: "dp", wide: true },
    ],
    st: [
      { key: "total", src: "st" },
      { key: "stVs", src: "st" },
      { key: "stWith", src: "st" },
      { key: "stWr", src: "st" },
    ],
  };
  const CELL_WIDTH = 50; // .MDH_Cell width + margin-right

  function columnTitle(key) {
    return {
      total: T.total,
      adv: T.vs,
      syn: T.with,
      stVs: T.vs,
      stWith: T.with,
      stWr: T.wrPos,
      wvs: T.wrvs,
      wr: T.wr,
      early: T.early,
      mid: T.mid,
      late: T.late,
    }[key];
  }

  function cellClass(col) {
    let cls = "MDH_Cell";
    if (col.src === "dp") cls += " MDH_SrcDp";
    if (col.src === "st") cls += " MDH_SrcSt";
    if (col.wide) cls += " MDH_WideOnly";
    return cls;
  }

  function buildTable(listId, specName) {
    const list = el(listId);
    if (!list) return null;
    const existing = state.tables[listId];
    if (existing && existing.specName === specName) return existing;
    list.RemoveAndDeleteChildren();
    const spec = COLUMNS[specName];
    const table = { specName: specName, spec: spec, rows: [] };
    state.tables[listId] = table;

    // Source groups above the column names (one label per run of columns from the same source)
    const groups = createPanel("Panel", list, listId + "_Groups");
    ["MDH_Row", "MDH_HeaderRow", "MDH_GroupRow"].forEach((c) => groups.AddClass(c));
    label(groups, "MDH_IconSpacer", "");
    label(groups, "MDH_Name", "");
    for (let i = 0; i < spec.length;) {
      let j = i;
      while (j < spec.length && spec[j].src === spec[i].src && !!spec[j].wide === !!spec[i].wide) j++;
      const src = spec[i].src;
      const text = src === "dp" ? T.groupDp : src === "st" ? (ST ? T.groupSt : T.stMissing) : "";
      let cls = "MDH_Group";
      if (src === "dp") cls += " MDH_SrcDp";
      if (src === "st") cls += " MDH_SrcSt";
      if (spec[i].wide) cls += " MDH_WideOnly";
      if (!src) cls = "MDH_Cell";
      const g = label(groups, cls, text);
      if (src) {
        try {
          g.style.width = (j - i) * CELL_WIDTH - 4 + "px";
        } catch (e) {}
      }
      i = j;
    }

    const header = createPanel("Panel", list, listId + "_Header");
    header.AddClass("MDH_Row");
    header.AddClass("MDH_HeaderRow");
    label(header, "MDH_IconSpacer", "");
    label(header, "MDH_Name", T.hero);
    spec.forEach((col) => {
      const h = label(header, cellClass(col), columnTitle(col.key));
      if (col.key === "total") {
        const tip = specName === "all" ? T.tooltipTotal : T.tooltipTotalOne;
        h.SetPanelEvent("onmouseover", () => showTooltip(h, tip));
        h.SetPanelEvent("onmouseout", hideTooltip);
      }
    });

    for (let i = 0; i < ROWS; i++) {
      const row = createPanel("Panel", list, listId + "_Row" + i);
      row.AddClass("MDH_Row");
      const icon = createPanel("DOTAHeroImage", row, "", {
        heroimagestyle: "landscape",
        scaling: "stretch-to-fit-y-preserve-aspect",
      });
      icon.AddClass("MDH_Icon");
      const cells = { icon: icon, name: label(row, "MDH_Name", "") };
      spec.forEach((col) => {
        let cls = "MDH_Cell";
        if (col.key === "total") cls += " MDH_Total";
        if (col.wide) cls += " MDH_WideOnly";
        cells[col.key] = label(row, cls, "");
      });
      const entry = { row: row, cells: cells, tooltip: "", heroId: 0 };
      row.SetPanelEvent("onmouseover", () => {
        if (entry.tooltip) showTooltip(row, entry.tooltip);
      });
      row.SetPanelEvent("onmouseout", hideTooltip);
      row.SetPanelEvent("onactivate", () => {
        state.detailHero = state.detailHero === entry.heroId ? 0 : entry.heroId;
        try {
          update(true);
        } catch (e) {}
      });
      table.rows.push(entry);
    }
    return table;
  }

  function setValue(lbl, value) {
    lbl.text = fmt(value);
    lbl.SetHasClass("MDH_Good", value > 0.05);
    lbl.SetHasClass("MDH_Bad", value < -0.05);
  }

  function setWinrate(lbl, wr) {
    lbl.text = wr ? wr.toFixed(1) + "%" : "—";
    lbl.SetHasClass("MDH_Good", wr >= 51);
    lbl.SetHasClass("MDH_Bad", wr > 0 && wr <= 49);
  }

  function setDash(lbl) {
    lbl.text = "—";
    lbl.SetHasClass("MDH_Good", false);
    lbl.SetHasClass("MDH_Bad", false);
  }

  function tooltipFor(r, source) {
    const lines = [heroDisplayName(r.hero) + (r.fit === 1 ? " (" + T.situational + ")" : "")];
    const showDp = source !== "st";
    const showSt = source !== "dp" && !!ST;
    const part = (list) =>
      list
        .slice()
        .sort((a, b) => (showDp ? b[1] - a[1] : b[2] - a[2]))
        .map((p) => {
          const vals = [];
          if (showDp) vals.push((showSt ? T.groupDp + " " : "") + fmt(p[1]));
          if (showSt) vals.push((showDp ? T.groupSt + " " : "") + fmt(p[2]) + "%");
          return heroDisplayName(DATA.heroes[p[0]]) + " " + vals.join(" / ");
        })
        .join(", ");
    if (r.vsList.length) lines.push(T.vsLine + ": " + part(r.vsList));
    if (r.withList.length) lines.push(T.withLine + ": " + part(r.withList));
    return lines.join("\n");
  }

  function renderTable(listId, specName, results) {
    const table = buildTable(listId, specName);
    if (!table) return;
    for (let i = 0; i < table.rows.length; i++) {
      const entry = table.rows[i];
      const r = results[i];
      entry.row.visible = !!r;
      if (!r) continue;
      const c = entry.cells;
      try {
        c.icon.heroid = r.hero.id;
      } catch (e) {
        try {
          c.icon.heroname = r.hero.npc;
        } catch (e2) {}
      }
      c.name.text = heroDisplayName(r.hero) + (r.fit === 1 ? "*" : "");
      entry.heroId = r.hero.id;
      entry.row.SetHasClass("MDH_Selected", state.detailHero === r.hero.id);
      table.spec.forEach((col) => {
        const lbl = c[col.key];
        if (col.src === "st" && !ST) return setDash(lbl);
        if (col.key === "stWr") return setWinrate(lbl, r.stWr);
        if (col.key === "wr") return setWinrate(lbl, r.hero.wr);
        if (col.key === "early") return setValue(lbl, r.hero.stage[0]);
        if (col.key === "mid") return setValue(lbl, r.hero.stage[1]);
        if (col.key === "late") return setValue(lbl, r.hero.stage[2]);
        setValue(lbl, r[col.key]);
      });
      entry.tooltip = tooltipFor(r, specName);
    }
  }

  function itemDisplayName(name) {
    try {
      const loc = $.Localize("#DOTA_Tooltip_ability_" + name);
      if (loc && loc.charAt(0) !== "#" && loc.indexOf("DOTA_Tooltip") === -1) return loc;
    } catch (e) {}
    return name.replace("item_", "").replace(/_/g, " ");
  }

  function renderItems(results, draft, pos) {
    const box = el("MDH_ItemsBox");
    const list = el("MDH_ItemsList");
    const title = el("MDH_ItemsTitle");
    if (!box || !list || !title) return;
    if (!ST) {
      box.visible = false;
      return;
    }
    box.visible = true;
    if (state.itemSlots.length === 0) {
      for (let i = 0; i < ITEM_SLOTS; i++) {
        const slot = createPanel("Panel", list, "MDH_Item" + i);
        slot.AddClass("MDH_ItemSlot");
        const img = createPanel("DOTAItemImage", slot, "", { scaling: "stretch-to-fit-y-preserve-aspect" });
        img.AddClass("MDH_ItemImage");
        const wr = label(slot, "MDH_ItemWr", "");
        const entry = { slot: slot, img: img, wr: wr, tooltip: "" };
        slot.SetPanelEvent("onmouseover", () => {
          if (entry.tooltip) showTooltip(slot, entry.tooltip);
        });
        slot.SetPanelEvent("onmouseout", hideTooltip);
        state.itemSlots.push(entry);
      }
    }

    // Hero for the item list: the clicked row, else your own pick, else the top suggestion
    const me = draft.allies.filter((a) => a.local)[0];
    let heroId = state.detailHero || (me && me.hero) || (results[0] ? results[0].hero.id : 0);
    const c = heroIndexById[heroId];
    let itemPos = pos;
    let items = c !== undefined && pos ? ST.items[heroId + ":" + pos] : null;
    if (!items && c !== undefined) {
      itemPos = mainPosition(c);
      items = ST.items[heroId + ":" + itemPos];
    }
    const heroName = c !== undefined ? heroDisplayName(DATA.heroes[c]) : "";
    title.text =
      T.itemsTitle +
      (heroName ? " · " + heroName + (itemPos ? " · " + T.pos + " " + itemPos : "") : "") +
      (items ? "" : " — " + T.itemsNone) +
      (state.detailHero ? "" : "  (" + T.clickHint + ")");

    for (let i = 0; i < state.itemSlots.length; i++) {
      const entry = state.itemSlots[i];
      const item = items ? items[i] : null;
      entry.slot.visible = !!item;
      if (!item) continue;
      try {
        entry.img.itemname = item[0];
      } catch (e) {}
      const wr = item[1] / 10;
      entry.wr.text = wr.toFixed(1) + "%";
      entry.wr.SetHasClass("MDH_Good", wr >= 52);
      entry.wr.SetHasClass("MDH_Bad", wr < 48);
      entry.tooltip = itemDisplayName(item[0]) + "\nWR " + wr.toFixed(1) + "% · " + item[2] + " " + T.matches;
    }
  }

  function stratzStatusText() {
    if (ST) return "STRATZ " + (CFG.stratzBracket || "");
    if (CFG.stratzError) return T.stMissing + " (" + CFG.stratzError + ")";
    if (!CFG.stratzToken) return T.stMissing + " (" + T.noToken + ")";
    return T.stMissing;
  }

  function setStatus(text) {
    const s = el("MDH_Status");
    if (s) s.text = text;
  }

  function nearestSize(scale) {
    let best = 3;
    for (let i = MIN_SIZE; i <= MAX_SIZE; i++) {
      if (Math.abs(SIZE_TO_SCALE[i] - scale) < Math.abs(SIZE_TO_SCALE[best] - scale)) best = i;
    }
    return best;
  }

  function applyLayoutClasses() {
    const root = el("MDH_Root");
    const win = el("MDH_Window");
    if (!root || !win) return;
    // Size classes are a fallback in case inline ui-scale is not supported
    const size = nearestSize(state.scale);
    for (let i = MIN_SIZE; i <= MAX_SIZE; i++) root.SetHasClass("MDH_Size" + i, i === size);
    try {
      win.style.uiScale = state.scale + "%";
    } catch (e) {}
    try {
      win.style.width = state.width + "px";
    } catch (e) {}
    const splitNow = state.split && !!ST;
    root.SetHasClass("MDH_Wide", state.width >= (splitNow ? SPLIT_WIDE_THRESHOLD : WIDE_THRESHOLD));
    root.SetHasClass("MDH_Split", splitNow);
    const split = el("MDH_BtnSplit");
    if (split) split.SetHasClass("MDH_Active", splitNow);
    root.SetHasClass("MDH_Free", state.free);
    if (state.free) {
      try {
        root.style.position = Math.round(state.left) + "px " + Math.round(state.top) + "px 0px";
      } catch (e) {}
    } else {
      try {
        root.style.position = null;
      } catch (e) {}
    }
    root.SetHasClass("MDH_Collapsed", state.collapsed);
    root.SetHasClass("MDH_Menu", IN_MENU);
    root.SetHasClass("MDH_Hidden", state.hidden);
    root.SetHasClass("MDH_Left", CFG.side === "left");
    for (let p = 0; p <= 5; p++) {
      const b = el("MDH_Pos" + p);
      if (b) b.SetHasClass("MDH_Active", state.manualPos === p);
    }
  }

  function describePositions(draft, positions) {
    const parts = [];
    draft.allies.forEach((a) => {
      const info = positions[a.pid];
      if (!info || a.local) return;
      const h = a.hero ? DATA.heroes[heroIndexById[a.hero]] : null;
      const lane = T.lanes[info.lane] || "?";
      parts.push((h ? heroDisplayName(h) : "?") + " " + (info.pos || "?") + (info.sure ? "" : "?") + " (" + lane + ")");
    });
    return parts.join(" · ");
  }

  // ------------------------------------------------------------------ debug

  function dumpPanel(panel, depth, maxDepth) {
    if (!panel || depth > maxDepth) return "";
    const pad = new Array(depth + 1).join("  ");
    let line = pad + "<" + (panel.paneltype || "Panel");
    if (panel.id) line += ' id="' + panel.id + '"';
    if (panel.actualclassnames) line += ' class="' + panel.actualclassnames + '"';
    try {
      line += " xy=" + Math.round(panel.actualxoffset) + "," + Math.round(panel.actualyoffset);
      line += " wh=" + Math.round(panel.actuallayoutwidth) + "x" + Math.round(panel.actuallayoutheight);
    } catch (e) {}
    try {
      if (panel.paneltype === "DOTAHeroImage") line += " heroid=" + panel.heroid + " heroname=" + panel.heroname;
    } catch (e) {}
    try {
      if (panel.paneltype === "Label" && panel.text) line += ' text="' + panel.text + '"';
    } catch (e) {}
    let out = line + ">\n";
    const count = panel.GetChildCount();
    for (let i = 0; i < count; i++) out += dumpPanel(panel.GetChild(i), depth + 1, maxDepth);
    return out;
  }

  function updateDebug(draft, icons, positions) {
    if (!CFG.debug) return;
    let text = "local=" + draft.local + " team=" + draft.team + " tentative=" + draft.tentative + "\n";
    text += "allies=" + JSON.stringify(draft.allies) + "\nenemies=" + JSON.stringify(draft.enemies) + "\n";
    text += "icons=" + JSON.stringify(icons) + "\npositions=" + JSON.stringify(positions) + "\n";
    try {
      text += "localInfo=" + JSON.stringify(Game.GetLocalPlayerInfo()) + "\n";
    } catch (e) {}
    ["HeroPickMinimap", "StrategyMinimap", "AllyHeroes"].forEach((id) => {
      const p = el(id);
      text += "--- " + id + "\n" + (p ? dumpPanel(p, 0, 3) : "(not found)\n");
    });
    if (text === state.lastDebug) return;
    state.lastDebug = text;
    const entry = el("MDH_Debug");
    if (entry) entry.text = text;
    $.Msg("[Draft Helper]\n" + text);
  }

  // ------------------------------------------------------------------ main loop

  // Prints the players (team, hero, Steam ID) to the console for the player info window in Minify,
  // which reads the console through -netconport. `status` alone only has names, ping and loss.
  function emitBridge(draft) {
    if (!CFG.bridge) return;
    const players = [];
    draft.allies.concat(draft.enemies).forEach((p) => {
      let info = null;
      try {
        info = Game.GetPlayerInfo(p.pid);
      } catch (e) {}
      let name = "";
      try {
        name = (info && info.player_name) || Players.GetPlayerName(p.pid) || "";
      } catch (e) {}
      players.push({
        pid: p.pid,
        team: Players.GetTeam(p.pid),
        name: name,
        steamid: info && info.player_steamid ? String(info.player_steamid) : "",
        hero: p.hero || 0,
        local: !!p.local,
      });
    });
    const text = JSON.stringify({ localTeam: draft.team, players: players });
    const now = Date.now() / 1000;
    if (text === state.lastBridge && now - state.lastBridgeTime < 5) return;
    state.lastBridge = text;
    state.lastBridgeTime = now;
    $.Msg("MDH_BRIDGE " + text);
  }

  function update(force) {
    if (!DATA) {
      setStatus(T.noData);
      return;
    }
    let draft;
    try {
      draft = readDraft();
    } catch (e) {
      draft = null;
    }
    if (!draft) {
      setStatus(T.spectator);
      return;
    }

    if (!draft.meta) {
      try {
        emitBridge(draft);
      } catch (e) {}
    }

    const icons = draft.meta || CFG.autoPosition === false ? [] : readMinimapIcons();
    const positions = detectPositions(draft, icons);
    const mine = positions[draft.local];
    const autoPos = mine && mine.pos ? mine.pos : 0;
    const pos = state.manualPos || autoPos;

    const signature = JSON.stringify([
      draft,
      icons.map((i) => [i.hero, i.lane]),
      pos,
      state.manualPos,
      state.detailHero,
      state.split,
    ]);
    updateDebug(draft, icons, positions);
    if (!force && signature === state.lastSignature) return;
    state.lastSignature = signature;

    const list2 = el("MDH_List2");
    let itemResults;
    if (state.split && ST) {
      renderTable("MDH_List", "dp", recommend(draft, pos, "dp"));
      itemResults = recommend(draft, pos, "st");
      renderTable("MDH_List2", "st", itemResults);
      if (list2) list2.visible = true;
    } else {
      itemResults = recommend(draft, pos, "all");
      renderTable("MDH_List", "all", itemResults);
      if (list2) list2.visible = false;
    }
    renderItems(itemResults, draft, pos);

    const enemiesPicked = draft.enemies.filter((e) => e.hero).length;
    const alliesPicked = draft.allies.filter((a) => a.hero && !a.local).length;
    let posText;
    if (state.manualPos) posText = state.manualPos + " (" + T.manual + ")";
    else if (autoPos)
      posText =
        autoPos + (mine.sure ? "" : "?") + " (" + T.auto.toLowerCase() + ": " + (T.lanes[mine.lane] || "") + ")";
    else posText = T.any + " (" + T.autoUnknown + ")";

    if (draft.meta) {
      setStatus(
        "dotapicker " +
          DATA.patch +
          " · " +
          stratzStatusText() +
          " · " +
          (CFG.bracketName || "") +
          " · " +
          T.meta +
          " · " +
          T.pos +
          ": " +
          (state.manualPos || T.metaPick),
      );
      return;
    }

    let status =
      "dotapicker " +
      DATA.patch +
      " · " +
      stratzStatusText() +
      " · " +
      (CFG.bracketName || "") +
      " · " +
      enemiesPicked +
      " " +
      T.enemies +
      ", " +
      alliesPicked +
      " " +
      T.allies +
      " · " +
      T.yourPos +
      ": " +
      posText;
    const allies = describePositions(draft, positions);
    if (allies) status += "\n" + allies;
    setStatus(status);
  }

  function tick() {
    try {
      update(false);
    } catch (e) {
      $.Msg("[Draft Helper] " + e);
    }
    $.Schedule(TICK_SECONDS, tick);
  }

  // ------------------------------------------------------------------ commands

  // ------------------------------------------------------------------ persistence
  // Panorama mods cannot write files; the state is kept on the top-level UI panel,
  // which lives for the whole Dota session, so it survives between matches.

  function topPanel() {
    let p = ctx();
    while (p && p.GetParent()) p = p.GetParent();
    return p;
  }

  function stateAttribute() {
    return STATE_ATTRIBUTE_BASE + (IN_MENU ? "_menu" : "");
  }

  function saveState() {
    try {
      const data = {
        scale: state.scale,
        width: state.width,
        free: state.free,
        left: state.left,
        top: state.top,
        collapsed: state.collapsed,
        split: state.split,
      };
      data.hidden = state.hidden;
      topPanel().SetAttributeString(stateAttribute(), JSON.stringify(data));
    } catch (e) {}
  }

  function loadState() {
    try {
      const raw = topPanel().GetAttributeString(stateAttribute(), "");
      if (!raw) return;
      const data = JSON.parse(raw);
      if (data.scale) state.scale = clamp(data.scale, MIN_SCALE, MAX_SCALE);
      if (data.width) state.width = clamp(data.width, MIN_WIDTH, MAX_WIDTH);
      state.free = !!data.free;
      state.left = data.left || 0;
      state.top = data.top || 0;
      state.collapsed = !!data.collapsed;
      if (IN_MENU && typeof data.hidden === "boolean") state.hidden = data.hidden;
      if (typeof data.split === "boolean") state.split = data.split;
    } catch (e) {}
  }

  // ------------------------------------------------------------------ drag & resize
  // Panorama has no mouse-move events for HUD panels, so while the cursor is over a
  // handle (title bar, right edge, corner) the mouse is polled every frame.

  const drag = { hover: null, armed: false, mode: null, polling: false };

  function cursor() {
    const c = GameUI.GetCursorPosition();
    return { x: c[0], y: c[1] };
  }

  function screenScale() {
    // screen pixels per layout pixel of the HUD (window ui-scale excluded)
    const root = el("MDH_Root");
    const s = root ? root.actualuiscale_x : 1;
    return s > 0 ? s : 1;
  }

  function hover(kind) {
    drag.hover = kind;
    try {
      drag.armed = !GameUI.IsMouseDown(0);
    } catch (e) {
      drag.armed = false;
    }
    if (!drag.polling) {
      drag.polling = true;
      $.Schedule(0, dragTick);
    }
  }

  function unhover(kind) {
    if (drag.hover === kind) drag.hover = null;
  }

  function beginDrag(kind) {
    const win = el("MDH_Window");
    if (!win) return;
    const pos = win.GetPositionWithinWindow();
    const k = screenScale();
    drag.mode = kind;
    drag.start = cursor();
    drag.startLeft = pos.x / k;
    drag.startTop = pos.y / k;
    drag.startScale = state.scale;
    drag.startWidth = state.width;
    drag.startWinWidth = win.actuallayoutwidth || 1;
    if (!state.free) {
      // Switch from the docked (right/left aligned) layout to a free position
      state.free = true;
      state.left = drag.startLeft;
      state.top = drag.startTop;
      applyLayoutClasses();
    }
  }

  function moveDrag() {
    const c = cursor();
    const k = screenScale();
    const dx = c.x - drag.start.x;
    const dy = c.y - drag.start.y;
    if (drag.mode === "move") {
      const maxLeft = Game.GetScreenWidth() / k - 60;
      const maxTop = Game.GetScreenHeight() / k - 30;
      state.left = clamp(drag.startLeft + dx / k, 0, maxLeft);
      state.top = clamp(drag.startTop + dy / k, 0, maxTop);
    } else if (drag.mode === "scale") {
      // Corner: scale the whole window, following the cursor horizontally
      const factor = (drag.startWinWidth + dx) / drag.startWinWidth;
      state.scale = clamp(Math.round(drag.startScale * factor), MIN_SCALE, MAX_SCALE);
    } else if (drag.mode === "width") {
      // Right edge: stretch the window, the text size stays the same
      const px = dx / k / (state.scale / 100);
      state.width = clamp(Math.round(drag.startWidth + px), MIN_WIDTH, MAX_WIDTH);
    }
    applyLayoutClasses();
  }

  function dragTick() {
    let down = false;
    try {
      down = GameUI.IsMouseDown(0);
    } catch (e) {}
    if (!drag.mode && drag.hover) {
      if (!down) drag.armed = true;
      else if (drag.armed) beginDrag(drag.hover);
    }
    if (drag.mode) {
      if (down) moveDrag();
      else {
        drag.mode = null;
        saveState();
      }
    }
    if (drag.mode || drag.hover) $.Schedule(0, dragTick);
    else drag.polling = false;
  }

  function command(name) {
    if (name === "bigger") state.scale = clamp(state.scale + 10, MIN_SCALE, MAX_SCALE);
    else if (name === "smaller") state.scale = clamp(state.scale - 10, MIN_SCALE, MAX_SCALE);
    else if (name === "wide") state.width = state.width >= WIDE_THRESHOLD ? NORMAL_WIDTH : WIDE_WIDTH;
    else if (name === "dock") state.free = false;
    else if (name === "split") {
      state.split = !state.split;
      if (state.split && state.width < SPLIT_WIDTH) state.width = SPLIT_WIDTH;
      else if (!state.split && state.width >= SPLIT_WIDTH) state.width = NORMAL_WIDTH;
    } else if (name === "collapse") state.collapsed = !state.collapsed;
    else if (name === "hide") state.hidden = true;
    else if (name === "show") state.hidden = false;
    else if (name === "toggle") state.hidden = !state.hidden;
    else if (name.indexOf("pos") === 0) state.manualPos = parseInt(name.substring(3), 10) || 0;
    applyLayoutClasses();
    saveState();
    try {
      update(true);
    } catch (e) {
      $.Msg("[Draft Helper] " + e);
    }
  }

  function keyName(key) {
    return "key_" + (/^F\d+$/.test(key) ? key : key.toLowerCase());
  }

  function registerHotkey() {
    if (!IN_MENU) {
      try {
        Game.AddCommand(COMMAND_NAME, () => command("toggle"), "", 0);
      } catch (e) {}
    }
    const key = CFG.hotkey;
    if (!key || key === "None") return;
    try {
      $.RegisterKeyBind(ctx(), keyName(key), () => command("toggle"));
    } catch (e) {}
    if (CFG.globalBind && !IN_MENU) {
      try {
        Game.CreateCustomKeyBind(key, COMMAND_NAME);
      } catch (e) {}
    }
  }

  function init() {
    const debugEntry = el("MDH_Debug");
    if (debugEntry) debugEntry.visible = !!CFG.debug;
    const hk = el("MDH_HotkeyHint");
    if (hk) hk.text = CFG.hotkey && CFG.hotkey !== "None" ? CFG.hotkey : "";
    if (IN_MENU) state.hidden = true;
    loadState();
    applyLayoutClasses();
    registerHotkey();
    tick();
  }

  return { init: init, command: command, hover: hover, unhover: unhover };
})();

function MDH_Command(name) {
  MinifyDraftHelper.command(name);
}

function MDH_Hover(kind) {
  MinifyDraftHelper.hover(kind);
}

function MDH_Unhover(kind) {
  MinifyDraftHelper.unhover(kind);
}

$.Schedule(0.1, () => MinifyDraftHelper.init());
